import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, Popup } from 'react-leaflet';
import L from 'leaflet';
import markerIcon2x from 'leaflet/dist/images/marker-icon-2x.png';
import markerIcon from 'leaflet/dist/images/marker-icon.png';
import markerShadow from 'leaflet/dist/images/marker-shadow.png';
import API_BASE_URL from '../api/config';

// Create React App's bundler breaks Leaflet's default marker image paths,
// which shows up as broken/invisible terminal markers. Point them at the
// bundled images explicitly.
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow,
});

const boatIcon = new L.Icon({
  iconUrl: '/boat-icon.png',
  iconSize: [32, 32],
  iconAnchor: [16, 32],
});

const ANIMATION_STEPS = 50;   // boat moves 1/50 of the way per tick
const TICK_MS = 500;

const calculateDistance = ([lat1, lon1], [lat2, lon2]) => {
  const toRad = deg => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return (6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))).toFixed(2);
};

const LiveTracking = () => {
  const [stations, setStations] = useState({});       // { "High Court": [lat, lng], ... }
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [fromOptions, setFromOptions] = useState([]);
  const [toOptions, setToOptions] = useState([]);
  const [boats, setBoats] = useState([]);
  const [message, setMessage] = useState('');
  const [selectedBoat, setSelectedBoat] = useState(null);
  const [boatPosition, setBoatPosition] = useState(null);

  // Station coordinates + "From" list come from the backend, so names always match.
  useEffect(() => {
    fetch(`${API_BASE_URL}/api/stations`)
      .then(res => res.json())
      .then(data => setStations(Object.fromEntries(data.map(s => [s.name, [s.lat, s.lng]]))))
      .catch(err => console.error(err));

    fetch(`${API_BASE_URL}/api/routes/from`)
      .then(res => res.json())
      .then(data => setFromOptions(Array.isArray(data) ? data : []))
      .catch(err => {
        console.error(err);
        setMessage('⚠ Cannot reach the backend. Is it running on ' + API_BASE_URL + '?');
      });
  }, []);

  // When "From" changes, reload valid destinations and clear old results.
  useEffect(() => {
    setTo('');
    setBoats([]);
    setSelectedBoat(null);
    if (!from) {
      setToOptions([]);
      return;
    }
    fetch(`${API_BASE_URL}/api/routes/to?from_location=${encodeURIComponent(from)}`)
      .then(res => res.json())
      .then(data => setToOptions(Array.isArray(data) ? data : []))
      .catch(err => console.error(err));
  }, [from]);

  const handleSubmit = () => {
    if (!from || !to) {
      setMessage('Please select both From and To.');
      setBoats([]);
      return;
    }
    setSelectedBoat(null);
    fetch(`${API_BASE_URL}/api/live-tracking?from_location=${encodeURIComponent(from)}&to_location=${encodeURIComponent(to)}`)
      .then(res => res.json())
      .then(data => {
        const list = Array.isArray(data.boats) ? data.boats : [];
        setBoats(list);
        setMessage(list.length ? '' : '❌ No ferries found.');
      })
      .catch(err => {
        console.error(err);
        setMessage('⚠ Error fetching data.');
        setBoats([]);
      });
  };

  // Simulated movement from "From" to "To" for the selected boat.
  useEffect(() => {
    const start = stations[from];
    const end = stations[to];
    if (!selectedBoat || !start || !end) {
      setBoatPosition(null);
      return;
    }

    let step = 0;
    setBoatPosition(start);
    const interval = setInterval(() => {
      step += 1;
      const p = Math.min(step / ANIMATION_STEPS, 1);
      setBoatPosition([start[0] + p * (end[0] - start[0]), start[1] + p * (end[1] - start[1])]);
      if (p >= 1) clearInterval(interval);
    }, TICK_MS);

    return () => clearInterval(interval);
  }, [selectedBoat, from, to, stations]);

  return (
    <div>
      <h2>Live Tracking</h2>

      <div>
        <label>From: </label>
        <select value={from} onChange={e => setFrom(e.target.value)}>
          <option value="">-- Select From --</option>
          {fromOptions.map(loc => <option key={loc} value={loc}>{loc}</option>)}
        </select>

        <label> To: </label>
        <select value={to} onChange={e => setTo(e.target.value)} disabled={!from}>
          <option value="">-- Select To --</option>
          {toOptions.map(loc => <option key={loc} value={loc}>{loc}</option>)}
        </select>

        <button onClick={handleSubmit}>Enter</button>
        {message && <p>{message}</p>}
      </div>

      {boats.length > 0 && (
        <div>
          <h3>Available Ferries (click one to track it):</h3>
          <ul>
            {boats.map((boat, i) => (
              <li
                key={`${boat.boat_id}-${boat.departure_time}-${i}`}
                onClick={() => setSelectedBoat(boat)}
                style={{
                  cursor: 'pointer',
                  marginBottom: '6px',
                  fontWeight: selectedBoat === boat ? 'bold' : 'normal',
                }}
              >
                🛥 Boat <strong>{boat.boat_id}</strong> — departs <strong>{boat.departure_time}</strong>,
                arrives <strong>{boat.arrival_time}</strong> ({boat.route})
              </li>
            ))}
          </ul>
        </div>
      )}

      {selectedBoat && boatPosition && (
        <MapContainer
          key={`${from}-${to}`}           // re-centre the map when the route changes
          center={stations[from]}
          zoom={13}
          style={{ height: '400px', marginTop: '20px' }}
        >
          <TileLayer
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            attribution="&copy; OpenStreetMap contributors"
          />
          <Marker position={stations[from]}><Popup>{from}</Popup></Marker>
          <Marker position={stations[to]}><Popup>{to}</Popup></Marker>
          <Marker position={boatPosition} icon={boatIcon}>
            <Popup>
              {selectedBoat.boat_id}: 📍 {calculateDistance(boatPosition, stations[to])} km to {to}
            </Popup>
          </Marker>
          <Polyline positions={[stations[from], stations[to]]} color="blue" />
        </MapContainer>
      )}
    </div>
  );
};

export default LiveTracking;
